// editorReserve pre-sizes an editor host to its query's line count so the
// CodeMirror mount doesn't shift the layout below it - the M5-era jump fix,
// generalized: a fixed base height only covers one-line queries, and M9's
// open-in-logs flows made multi-line queries in the URL common.
// The host publishes the height as --cm-reserve so the .cm-editor min-height
// agrees with it exactly (over-estimates read as normal editor whitespace).
func editorReserve(q string, basePx, linePx, maxPx int) templ.SafeCSS {
	lines := strings.Count(strings.TrimRight(q, "\n"), "\n") + 1
	h := min(basePx+(lines-1)*linePx, maxPx)
	return templ.SafeCSS(fmt.Sprintf("min-height: %dpx; --cm-reserve: %dpx", h, h))
}

// shared hosts: 14px font (~20px lines), 3.5rem base, 8rem max-height
